def get_attachment(request: Request, filename: str) -> Response:
    path = os.path.join(ATTACHMENT_DIR, filename)
    if not os.path.isfile(path):
        raise HTTPError(404, "attachment not found")
    with open(path, "rb") as handle:
        return Response.file(handle.read(), filename=os.path.basename(path))

